package com.github.se.jdrnexus.model.soundboard

import androidx.room.Embedded
import androidx.room.Entity
import androidx.room.Index
import androidx.room.PrimaryKey
import androidx.room.Relation

/*
 * The Room tables behind SoundboardRepositoryLocal. Each table has its own row type, separate from
 * the model in Soundboard.kt: a row holds what the database needs (keys, positions, owner), while
 * the model holds what the screens need.
 *
 * Soundboards and playlists get a numeric key generated by Room. The model's ids are only unique
 * per user (soundboards) or per soundboard (playlists), so they cannot link rows on their own.
 */

/**
 * One soundboard of one user.
 *
 * @property soundboardKey Key generated by Room. Keys grow with each new soundboard, so sorting by
 *   key gives the creation order.
 * @property userId The owner's Firebase Auth id.
 * @property id The model's [Soundboard.id], unique among the user's soundboards.
 */
@Entity(tableName = "soundboards", indices = [Index(value = ["userId", "id"], unique = true)])
internal data class SoundboardEntity(
    @PrimaryKey(autoGenerate = true) val soundboardKey: Long = 0,
    val userId: String,
    val id: String,
    val name: String,
    val ambienceVolume: Float,
    val effectsVolume: Float,
)

/**
 * One ambience playlist of a soundboard.
 *
 * @property playlistKey Key generated by Room, which the tracks point to.
 * @property position Index of the playlist in [Soundboard.playlists].
 * @property id The model's [AmbiencePlaylist.id].
 */
@Entity(tableName = "soundboard_playlists", indices = [Index("soundboardKey")])
internal data class PlaylistEntity(
    @PrimaryKey(autoGenerate = true) val playlistKey: Long = 0,
    val soundboardKey: Long,
    val position: Int,
    val id: String,
    val name: String,
)

/**
 * One track of a playlist.
 *
 * @property position Index of the track in [AmbiencePlaylist.tracks].
 * @property audioId The [AudioFileEntity.id] of the mp3 the track plays.
 */
@Entity(tableName = "soundboard_tracks", primaryKeys = ["playlistKey", "position"])
internal data class TrackEntity(
    val playlistKey: Long,
    val position: Int,
    val name: String,
    val audioId: String,
)

/**
 * One sound effect of a soundboard.
 *
 * @property position Index of the effect in [Soundboard.effects].
 * @property icon Stored by Room as the enum constant's name.
 * @property audioId The [AudioFileEntity.id] of the mp3 the effect plays.
 */
@Entity(tableName = "soundboard_effects", primaryKeys = ["soundboardKey", "position"])
internal data class EffectEntity(
    val soundboardKey: Long,
    val position: Int,
    val name: String,
    val icon: SoundEffectIcon,
    val audioId: String,
)

/**
 * One imported mp3, saved in a soundboard or not yet. The file itself is in the app's private
 * storage, named after [id]: the path is not stored, so moving the app's storage cannot break it.
 *
 * @property userId The Firebase Auth id of the user who imported it.
 */
@Entity(tableName = "soundboard_audio_files", indices = [Index("userId")])
internal data class AudioFileEntity(
    @PrimaryKey val id: String,
    val userId: String,
    val durationMs: Long,
)

/** A track with the audio file it plays, which Room loads with it. */
internal data class TrackWithAudio(
    @Embedded val track: TrackEntity,
    @Relation(parentColumn = "audioId", entityColumn = "id") val audio: AudioFileEntity,
)

/** A playlist with its tracks, which Room loads with it. */
internal data class PlaylistWithTracks(
    @Embedded val playlist: PlaylistEntity,
    @Relation(
        entity = TrackEntity::class,
        parentColumn = "playlistKey",
        entityColumn = "playlistKey",
    )
    val tracks: List<TrackWithAudio>,
)

/** An effect with the audio file it plays, which Room loads with it. */
internal data class EffectWithAudio(
    @Embedded val effect: EffectEntity,
    @Relation(parentColumn = "audioId", entityColumn = "id") val audio: AudioFileEntity,
)

/**
 * A soundboard with everything it contains, which Room loads with it. Room does not keep the order
 * of the related rows, so the positions give it back.
 */
internal data class SoundboardWithContent(
    @Embedded val soundboard: SoundboardEntity,
    @Relation(
        entity = PlaylistEntity::class,
        parentColumn = "soundboardKey",
        entityColumn = "soundboardKey",
    )
    val playlists: List<PlaylistWithTracks>,
    @Relation(
        entity = EffectEntity::class,
        parentColumn = "soundboardKey",
        entityColumn = "soundboardKey",
    )
    val effects: List<EffectWithAudio>,
)
